// Decide what the flow does for each trigger. Every CONNECT carries a token fetched just before it.
//   start   -> fetch a token, then connect
//   refresh -> fetch a token, then force a reconnect so the new CONNECT carries it
//   watch   -> if the link is down: fetch a token, then connect (a new token on every watch reconnect)
//              if the link is up: do nothing (no token request every 30 s)
// The link state comes from the status-link node (flow.zbLinkUp).
const topic = msg.topic || '';
if (topic === 'watch' && flow.get('zbLinkUp') === true) {
    return null;
}
msg.cycle = (topic === 'refresh');
return msg;

// OAuth client-credentials request for a table-scoped Zerobus token.
// All settings come from environment variables. Nothing secret is written into the flow.
function need(name) {
    const value = env.get(name);
    if (!value) { throw new Error('Set the ' + name + ' environment variable'); }
    return value;
}
const workspaceUrl = need('DATABRICKS_WORKSPACE_URL').replace(/\/+$/, '');
const workspaceId = need('DATABRICKS_WORKSPACE_ID');
const table = need('DATABRICKS_TABLE_NAME');
const [catalog, schema] = table.split('.');
const authorizationDetails = [
    { type: 'unity_catalog_privileges', privileges: ['USE CATALOG'], object_type: 'CATALOG', object_full_path: catalog },
    { type: 'unity_catalog_privileges', privileges: ['USE SCHEMA'], object_type: 'SCHEMA', object_full_path: catalog + '.' + schema },
    { type: 'unity_catalog_privileges', privileges: ['SELECT', 'MODIFY'], object_type: 'TABLE', object_full_path: table },
];
const basic = Buffer.from(need('DATABRICKS_CLIENT_ID') + ':' + need('DATABRICKS_CLIENT_SECRET')).toString('base64');
msg.method = 'POST';
msg.url = workspaceUrl + '/oidc/v1/token';
msg.headers = { 'Content-Type': 'application/x-www-form-urlencoded', Authorization: 'Basic ' + basic };
msg.payload = new URLSearchParams({
    grant_type: 'client_credentials',
    scope: 'all-apis',
    resource: 'api://databricks/workspaces/' + workspaceId + '/zerobusDirectWriteApi',
    authorization_details: JSON.stringify(authorizationDetails),
}).toString();
return msg;

// Keep the token in flow context (memory only) and pass the message on. Never log the token.
let response = null;
try { response = JSON.parse(msg.payload); } catch (err) { response = null; }
if (msg.statusCode !== 200 || !response || !response.access_token) {
    node.error('Token request failed with HTTP ' + msg.statusCode + '; nothing connected');
    return null;
}
flow.set('zbToken', response.access_token);
flow.set('zbTokenAt', Date.now());
// FNV-1a 32-bit fingerprint for logs only (function nodes have no crypto module).
let hash = 0x811c9dc5;
const token = response.access_token;
for (let i = 0; i < token.length; i++) { hash ^= token.charCodeAt(i); hash = Math.imul(hash, 0x01000193) >>> 0; }
node.warn('token ' + hash.toString(16).padStart(8, '0') + ' fetched (expires_in ' + response.expires_in + 's)');
delete msg.payload; delete msg.headers; delete msg.url; delete msg.method; delete msg.statusCode;
return msg;

// Connect action for the mqtt out node. The CONNECT carries the token that was fetched just before
// (start, refresh, or a watch reconnect), so no CONNECT reuses an older token.
// msg.cycle (refresh) forces a disconnect and reconnect so the new token is used.
// Without force, a connect while already connected is refused by the node, which the catch node
// treats as the normal "link is up" answer.
const token = flow.get('zbToken');
if (!token) { node.error('No token cached; skipping connect'); return null; }
msg.action = 'connect';
msg.broker = {
    broker: env.get('ZEROBUS_MQTT_HOST'),
    port: 8883,
    usetls: true,
    protocolVersion: 5,
    clientid: 'zerobus-node-red-' + Date.now(),
    userProperties: JSON.stringify({
        Authorization: 'Bearer ' + token,
        'x-databricks-zerobus-table-name': env.get('DATABRICKS_TABLE_NAME'),
    }),
    force: msg.cycle === true,
};
delete msg.payload; delete msg.cycle; delete msg.topic;
return msg;

// Demo app: a six-sided die roll. Publishes once every two seconds.
msg.topic = env.get('DATABRICKS_TABLE_NAME');
msg.qos = 1;
msg.payload = {
    roll_id: Date.now(),
    player: 'node-red-demo',
    die_sides: 6,
    roll: 1 + Math.floor(Math.random() * 6),
    rolled_at: new Date().toISOString(),
};
return msg;

// One record whose roll is a string, but the table column is INT (a type mismatch).
// With the rescue column, the server stores the value in rescue and keeps the connection up.
msg.topic = env.get('DATABRICKS_TABLE_NAME');
msg.qos = 1;
msg.payload = {
    roll_id: Date.now(),
    player: 'node-red-demo',
    die_sides: 6,
    roll: 'six',
    rolled_at: new Date().toISOString(),
};
return msg;

// One record with a field the table does not have (extra_field).
// With the rescue column, the server stores the field in rescue and keeps the connection up.
msg.topic = env.get('DATABRICKS_TABLE_NAME');
msg.qos = 1;
msg.payload = {
    roll_id: Date.now(),
    player: 'node-red-demo',
    die_sides: 6,
    roll: 1 + Math.floor(Math.random() * 6),
    rolled_at: new Date().toISOString(),
    extra_field: 'hello',
};
return msg;

// A payload that is not JSON. The server answers PUBACK 0x99 (Payload format invalid),
// stores nothing, and keeps the connection up, with or without the rescue column.
msg.topic = env.get('DATABRICKS_TABLE_NAME');
msg.qos = 1;
msg.payload = 'not json ' + Date.now() + ' ((';
return msg;

// The mqtt out node reports "connected" or "disconnected" as its status. The watch trigger reads the flag.
const text = (msg.status && msg.status.text) || '';
if (/common\.status\.connected$/.test(text)) { flow.set('zbLinkUp', true); }
else if (/common\.status\.disconnected$/.test(text)) { flow.set('zbLinkUp', false); }
return null;

// Connect while connected is expected from the watch trigger; report anything else.
// A publish error here is a PUBACK with a reason code, e.g. 'Payload format invalid' (0x99) for non-JSON.
// A type mismatch or extra field gives no error when the rescue column is present.
const text = (msg.error && msg.error.message) || '';
// The node's text for a connect while connected is "Disconnect from broker before connecting".
if (text.indexOf('Disconnect from broker before connecting') === -1) {
    node.warn('mqtt out: ' + text);
}
return null;
